type Shape = { kind: 'circle' } | { kind: 'square' };

function getArea(s: Shape) {
  switch (s.kind) {
    case 'circle': return Math.PI;
    case 'square': return 1;
    default:
      const _exhaustiveCheck: never = s;
      return _exhaustiveCheck;
  }
}

